import{_ as t,a0 as d,w as o,s as r,I as n,x as a,a1 as i,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux 包管理器比較：dnf 和 apt | LCTT x X-CMD","titleTemplate":false,"description":"Linux 包管理器比較：dnf 和 apt | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 包管理器比較：dnf 和 apt | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 包管理器比較：dnf 和 apt | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210719 Linux package managers- dnf vs apt","title":"Linux 包管理器比較：dnf 和 apt","tag":"202107","desc":""},"relativePath":"202107/20210719 Linux package managers- dnf vs apt.md","filePath":"[post].md"}'),g={name:"202107/20210719 Linux package managers- dnf vs apt.md"};function h(u,s,c,k,b,f){const e=d("Link");return o(),r("div",null,[s[34]||(s[34]=n("h1",{id:"linux-包管理器比較-dnf-和-apt",tabindex:"-1"},[a("Linux 包管理器比較：dnf 和 apt "),n("a",{class:"header-anchor",href:"#linux-包管理器比較-dnf-和-apt","aria-label":"Permalink to “Linux 包管理器比較：dnf 和 apt”"},"​")],-1)),s[35]||(s[35]=n("blockquote",null,[n("p",null,"包管理器提供大致相同的功能：安裝、管理和移除應用，但是它們還是有一些不一樣的地方。")],-1)),s[36]||(s[36]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/27/083002sd5zzxu37yhiz6yc.jpg",alt:""})],-1)),n("p",null,[i(e,{href:"https://opensource.com/article/18/1/how-install-apps-linux"},{default:p(()=>[...s[0]||(s[0]=[a("在 Linux 系統上獲取一個應用",-1)])]),_:1}),s[1]||(s[1]=a(" 有多種方式。例如，有新的 Flatpak 和容器方式，也有 DEB 和 RPM 這樣一直以來經過考驗的方式。",-1))]),s[37]||(s[37]=l(`<p>並沒有一種通用的可以用於所有的操作系統的應用安裝程序。如今，因為有無數的開發者發佈軟件，這導致了大部分的操作系統使用了應用商店（包括第一方和第三方）、拖放式安裝，還有安裝嚮導。不同的開發者對於他們發佈的代碼有不同的需求，這直接導致了他們所選擇的安裝方式的不同。</p><p>Linux 開創了一種通過命令列安裝、管理、移除應用的包管理器的概念。<code>apt</code> 和 <code>dnf</code> 就是兩種較為常見的包管理器。<code>apt</code> 命令是用來管理 DEB 格式的包，<code>dnf</code> 命令是用來管理 RPM 格式的包。這兩種包管理器在理論上並不是完全互斥的，儘管在實際的實踐中，Linux 發行版通常只會使用到其中的一種。理論上，這兩種命令可以運行在同一個系統上，但是會造成安裝包的重疊，版本控制也會更加困難，命令也會是冗餘的。然而，如果你是在一個混合的 Linux 環境下工作，比如你的工作站運行的是一個發行版，同時需要與運行另外一種發行版的服務器進行交互，那麼你最好同時掌握這兩種包管理器。</p><h3 id="搜索應用" tabindex="-1">搜索應用 <a class="header-anchor" href="#搜索應用" aria-label="Permalink to “搜索應用”">​</a></h3><p>當你通過包管理器安裝一個應用時，你需要先知道包的名稱。通常，應用的名稱和包的名稱是一樣的。<code>dnf</code> 和 <code>apt</code> 驗證要安裝的包名的過程是完全相同的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf search zsh</span></span>
<span class="line"><span>====== Name Exactly Matched: zsh ======</span></span>
<span class="line"><span>zsh.x86_64 : Powerful interactive shell</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>使用 <code>apt</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt search zsh</span></span>
<span class="line"><span>Sorting... Done</span></span>
<span class="line"><span>Full Text Search... Done</span></span>
<span class="line"><span>csh/stable 20110502-4+deb10u1 amd64</span></span>
<span class="line"><span>  Shell with C-like syntax</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ddgr/stable 1.6-1 all</span></span>
<span class="line"><span>  DuckDuckGo from the terminal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>direnv/stable 2.18.2-2 amd64</span></span>
<span class="line"><span>  Utility to set directory specific environment variables</span></span>
<span class="line"><span></span></span>
<span class="line"><span>draai/stable 20180521-1 all</span></span>
<span class="line"><span>  Command-line music player for MPD</span></span>
<span class="line"><span>[...]</span></span></code></pre></div>`,7)),n("p",null,[s[3]||(s[3]=a("如果想通過 ",-1)),s[4]||(s[4]=n("code",null,"apt",-1)),s[5]||(s[5]=a(" 更快的獲取相關的搜索結果，你可以使用 ",-1)),i(e,{href:"https://opensource.com/article/18/5/getting-started-regular-expressions"},{default:p(()=>[...s[2]||(s[2]=[a("正則表達式",-1)])]),_:1}),s[6]||(s[6]=a("：",-1))]),s[38]||(s[38]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt search ^zsh</span></span>
<span class="line"><span>Sorting... Done</span></span>
<span class="line"><span>Full Text Search... Done</span></span>
<span class="line"><span>zsh/stable 5.7.1-1 amd64</span></span>
<span class="line"><span>  shell with lots of features</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="查找應用程序包" tabindex="-1">查找應用程序包 <a class="header-anchor" href="#查找應用程序包" aria-label="Permalink to “查找應用程序包”">​</a></h3><p>有一些命令是與其它命令捆綁在一起的，都在一個包中。在這種情況下，你可以通過包管理器去了解哪個包提供了你需要的命令。<code>dnf</code> 和 <code>apt</code> 命令在如何搜索這類元數據上是有區別的。</p><p>使用 <code>dnf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf provides pgrep</span></span>
<span class="line"><span>procps-ng-3.3.15-6.el8.x86_64 : System and process monitoring utilities</span></span>
<span class="line"><span>Repo        : baseos</span></span>
<span class="line"><span>Matched from:</span></span>
<span class="line"><span>Filename    : /usr/bin/pgrep</span></span></code></pre></div><p><code>apt</code> 命令使用子命令 <code>apt-file</code>。要使用 <code>apt-file</code>，你必須先安裝它，然後提示它更新緩存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install apt-file</span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>Building dependency tree      </span></span>
<span class="line"><span>Reading state information... Done</span></span>
<span class="line"><span>The following additional packages will be installed:</span></span>
<span class="line"><span>  libapt-pkg-perl libexporter-tiny-perl liblist-moreutils-perl libregexp-assemble-perl</span></span>
<span class="line"><span>The following NEW packages will be installed:</span></span>
<span class="line"><span>  apt-file libapt-pkg-perl libexporter-tiny-perl liblist-moreutils-perl libregexp-assemble-perl</span></span>
<span class="line"><span>0 upgraded, 5 newly installed, 0 to remove and 14 not upgraded.</span></span>
<span class="line"><span>Need to get 297 kB of archives.</span></span>
<span class="line"><span>After this operation, 825 kB of additional disk space will be used.</span></span>
<span class="line"><span>Do you want to continue? [Y/n] y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo apt-file update</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你可以通過 <code>apt-file</code> 搜索命令。你可以使用此命令進行廣泛的全局搜索，但假如你知道命令的執行路徑，它會更準確：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-file search /usr/bin/pgrep</span></span>
<span class="line"><span>pgreplay: /usr/bin/pgreplay              </span></span>
<span class="line"><span>procps: /usr/bin/pgrep</span></span></code></pre></div><h3 id="安裝應用程序" tabindex="-1">安裝應用程序 <a class="header-anchor" href="#安裝應用程序" aria-label="Permalink to “安裝應用程序”">​</a></h3><p>使用<code>apt</code> 和 <code>dnf</code> 安裝應用程序基本上是相同的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install zsh</span></span></code></pre></div><p>使用 <code>dnf</code>，你可以使用同樣的方式來安裝一個包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install zsh</span></span></code></pre></div>`,14)),n("p",null,[s[8]||(s[8]=a("許多基於 RPM 的發行版都具有組包安裝的特性，它會將有時表面相關的應用程序收集到一個易於安裝的目標中。例如，Fedora 中的 ",-1)),i(e,{href:"https://labs.fedoraproject.org/en/design-suite/"},{default:p(()=>[...s[7]||(s[7]=[a("Design Suite",-1)])]),_:1}),s[9]||(s[9]=a(" 組包就包含流行的創意應用程序。那些想要某一個創意應用程序的藝術家可能也想要類似的應用程序，選擇安裝一整個組包一個簡單而快速的方法，可以合理地開始建立一個數字工作室。你可以通過 ",-1)),s[10]||(s[10]=n("code",null,"group list",-1)),s[11]||(s[11]=a(" 來查看可用的組包（使用 ",-1)),s[12]||(s[12]=n("code",null,"-v",-1)),s[13]||(s[13]=a(" 來查看不帶空格的組名）：",-1))]),s[39]||(s[39]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf group list -v</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Available Groups:</span></span>
<span class="line"><span>   Container Management (container-management)</span></span>
<span class="line"><span>   RPM Development Tools (rpm-development-tools)</span></span>
<span class="line"><span>   Design Suite (design-suite)</span></span>
<span class="line"><span>   Development Tools (development)</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>使用 <code>group install</code> 子命令安裝 RPM 組包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf group install design-suite</span></span></code></pre></div><p>你可以使用 <code>@</code> 符號來減少輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install @design-suite</span></span></code></pre></div><h3 id="更新應用程序" tabindex="-1">更新應用程序 <a class="header-anchor" href="#更新應用程序" aria-label="Permalink to “更新應用程序”">​</a></h3><p>使用包管理器的一個優點是，它知道所有已經安裝的應用。這樣你不必去尋找應用程序的更新版本。相反，你可以通過包管理器去獲取更新的版本。</p><p><code>dnf</code> 和 <code>apt</code> 使用的子命令略有不同。因為 <code>apt</code> 保存了一個需要定期更新的緩存信息，它使用 <code>upgrade</code> 子命令來更新應用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt upgrade</span></span></code></pre></div><p>相比之下，<code>dnf</code> 命令在你每次使用時都會更新元信息，所以 <code>update</code> 和 <code>upgrade</code> 子命令是可以互換的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf upgrade</span></span></code></pre></div><p>這等同於：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update</span></span></code></pre></div><h3 id="移除應用程序" tabindex="-1">移除應用程序 <a class="header-anchor" href="#移除應用程序" aria-label="Permalink to “移除應用程序”">​</a></h3><p>如果你曾經嘗試在任何一個平台上手動刪除一個應用程序，你就會知道，應用程序刪除後，在硬盤上會殘留各種文件，比如首選項文件、數據或圖標。所以包管理器的另一個優點是，包管理器管理着包中安裝的每一個文件，可以很方便的刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf remove zsh</span></span></code></pre></div><p><code>remove</code> 子命令也適用於 <code>apt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt remove zsh</span></span></code></pre></div><p>使用 <code>apt</code> 命令刪除一個包並不會刪除已修改的用户配置文件，以防你意外刪除了包。如果你想通過 <code>apt</code> 命令刪除一個應用及其配置文件，請在你之前刪除過的應用程序上使用 <code>purge</code> 子命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt purge zsh</span></span></code></pre></div><p><code>apt</code> 和 <code>dnf</code> 都不會刪除家目錄中的數據和配置文件（即使使用 <code>purge</code> 子命令）。如果想要從家目錄中刪除數據，你必須手動操作（通常你可以在 <code>~/.config</code> 和 <code>~/.local</code> 文件中找到）。</p><h3 id="瞭解包管理" tabindex="-1">瞭解包管理 <a class="header-anchor" href="#瞭解包管理" aria-label="Permalink to “瞭解包管理”">​</a></h3><p>無論你選擇的發行版支持的是 <code>apt</code> 還是 <code>dnf</code>，這些命令的用途大致相同。它們可以幫助你安裝、更新和移除包。這兩種包管理器是目前最通用的包管理器。它們的語法元素在很大程度上是相同的，所以在兩者之間切換非常容易。</p><p><code>apt</code> 和 <code>dnf</code> 還有一些高級功能，例如倉庫管理，但這些功能並不像你使用 <code>search</code> 和 <code>install</code> 那樣頻繁。</p>`,24)),n("p",null,[s[16]||(s[16]=a("無論你更經常使用哪種包管理器，你都可以下載我們的 ",-1)),i(e,{href:"https://opensource.com/downloads/apt-cheat-sheet"},{default:p(()=>[...s[14]||(s[14]=[a("apt 備忘單",-1)])]),_:1}),s[17]||(s[17]=a(" 和 ",-1)),i(e,{href:"https://opensource.com/downloads/dnf-cheat-sheet"},{default:p(()=>[...s[15]||(s[15]=[a("dnf 備忘單",-1)])]),_:1}),s[18]||(s[18]=a("，以便你在最需要的時候可以查詢使用語法。",-1))]),s[40]||(s[40]=n("hr",null,null,-1)),n("p",null,[s[20]||(s[20]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/7/dnf-vs-apt"},{default:p(()=>[...s[19]||(s[19]=[a("https://opensource.com/article/21/7/dnf-vs-apt",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[21]||(s[21]=[a("Seth Kenlon",-1)])]),_:1}),s[26]||(s[26]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[22]||(s[22]=[a("lujun9972",-1)])]),_:1}),s[27]||(s[27]=a(" 譯者：",-1)),i(e,{href:"https://github.com/perfiffer"},{default:p(()=>[...s[23]||(s[23]=[a("perfiffer",-1)])]),_:1}),s[28]||(s[28]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[a("Linux中國",-1)])]),_:1}),s[33]||(s[33]=a(" 榮譽推出",-1))])])}const v=t(g,[["render",h]]);export{x as __pageData,v as default};
